# tasks
tasks={}
for f in glob.glob(root+'/tasks/items/*.yaml'):
    d=yaml.safe_load(open(f))
    tasks[d.get('id')]=d
running=[t for t,d in tasks.items() if d.get('status')=='running']
print("RUNNING TASKS:",sorted(running))
# roadmap_refs union
refs=set()
for t in running:
    for r in (tasks[t].get('roadmap_refs') or []): refs.add(r)
held=set()
for k,v in active.items():
    md=v.get('metadata') or {}
    own=md.get('owner') or v.get('owner')
    trefs=md.get('task_refs') or v.get('task_refs') or []
    if own in running or any(x in running for x in trefs) or k in refs:
        held.add(k)
def parent(k):
    v=items.get(k) or {}
    md=v.get('metadata') or {}
    return md.get('parent') or v.get('parent')
# ancestors of held (any status, but count active ones)
anc=set()
for k in list(held):
    p=parent(k)
    while p:
        if p in active: anc.add(p)
        p=parent(p)
anc-=held
left=set(active)-held-anc
print("HELD DIRECTLY (%d): %s"%(len(held),sorted(held)))
print("ACTIVE ANCESTORS (%d): %s"%(len(anc),sorted(anc)))
print("LEFTOVER (%d):"%len(left))
for k in sorted(left):
